SELECT e.master_id,e.album_id,e.title,e.disc,e.track,e.duration,e.instance_id,e.source_id,e.source_type,e.storage_object_id,e.suffix,e.instance_size,e.missing,e.tag_scanned,e.object_id,e.physical_key,e.object_size,e.entry_id,e.parent_id,e.path,e.kind,
 CASE WHEN sm.id IS NOT NULL AND si.id IS NOT NULL AND so.id IS NOT NULL AND se.id IS NOT NULL THEN 1 ELSE 0 END AS exact_match
FROM expected e
LEFT JOIN song_masters sm ON sm.id=e.master_id AND sm.album_id=e.album_id AND sm.title=e.title AND sm.track IS e.track AND sm.disc IS e.disc AND sm.duration=e.duration
LEFT JOIN song_instances si ON si.id=e.instance_id AND si.master_id=e.master_id AND si.source_id=e.source_id AND si.source_type=e.source_type AND si.storage_object_id=e.storage_object_id AND si.suffix=e.suffix AND si.size=e.instance_size AND si.missing=e.missing AND si.tag_scanned=e.tag_scanned
LEFT JOIN storage_objects so ON so.id=e.object_id AND so.physical_key=e.physical_key AND so.size=e.object_size
LEFT JOIN storage_entries se ON se.id=e.entry_id AND se.instance_id=e.instance_id AND se.object_id=e.object_id AND se.parent_id=e.parent_id AND se.path=e.path AND se.kind=e.kind
ORDER BY e.album_id,e.track,e.master_id;

SELECT a.id,a.name,a.sort_name,a.song_count,a.duration,a.size,
 (SELECT COUNT(*) FROM song_masters sm WHERE sm.album_id=a.id) AS actual_count,
 (SELECT COALESCE(SUM(sm.duration),0) FROM song_masters sm WHERE sm.album_id=a.id) AS actual_duration,
 (SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id=a.id) AS actual_size
FROM albums a WHERE a.id IN ('al-369dc39c99e3a1a27dc05b84aa30d1e1','pending-uploads') ORDER BY a.id;
SELECT
 (SELECT COUNT(*) FROM albums WHERE id='al-zhongchong-instrumentals-20260926' OR name='众虫皆歌（伴奏）') AS companion_album_conflicts,
 (SELECT COUNT(*) FROM album_display_groups WHERE id='ag-zhongchong-audio-versions-20260926' OR display_name='众虫皆歌') AS group_conflicts,
 (SELECT COUNT(*) FROM album_display_group_members WHERE album_id IN ('al-369dc39c99e3a1a27dc05b84aa30d1e1','al-zhongchong-instrumentals-20260926')) AS member_conflicts;
